"""navera_lite/rotations.py — rotation matrices, ZYX Euler angles and quaternions. Part of NAVERA Lite,
the course's teaching stack (mission 16). Written for the course; it is not NAVERA code.

Conventions (courses/_lib/CONVENTIONS.md §1–§4):
- World frame ENU (x = East, y = North, z = Up); body frame FLU (x = Forward/nose, y = Left, z = Up).
- A rotation matrix R maps body coordinates to world coordinates: v_world = R @ v_body. Its columns are
  the body axes written in the world frame (column 0 = where the nose points).
- Angles in RADIANS for the matrix and quaternion functions (as in ROS messages); the "human" outputs
  (heading_deg_from_q, rpy_human, q_angle_deg) are in DEGREES and say so in their names.
- ZYX Euler angles as in ROS (REP-103): R = Rz(yaw) @ Ry(pitch) @ Rx(roll). A POSITIVE ROS pitch turns
  the nose DOWN (rotation about +y = left); rpy_human reports pitch positive NOSE UP.
- Quaternions are (x, y, z, w): the scalar part LAST, as in ROS messages. Functions accept any sequence
  of 4 numbers (tuple, list, numpy array) and return numpy arrays.
"""
import math

import numpy as np

IDENTITY_Q = np.array([0.0, 0.0, 0.0, 1.0])      # (x, y, z, w): no rotation (level, nose east)


# from mission 16 — finished: read it, use it, do not change it
def q_normalize(q):
    """q scaled to length 1, as a numpy array (x, y, z, w). Raises ValueError for a zero quaternion.

    Example: q_normalize((0.0, 0.0, 3.0, 4.0)) → array([0. , 0. , 0.6, 0.8])
    """
    q = np.asarray(q, dtype=float).reshape(4)
    n = float(np.linalg.norm(q))
    if not math.isfinite(n) or n < 1e-12:
        raise ValueError(f"a quaternion must have a non-zero finite length, got {q.tolist()}")
    return q / n


# ====================================================================== session 1 — matrices and Euler angles

# from mission 16 — finished: read it, use it, do not change it
def rot_x(angle_rad):
    """Rotation by angle_rad (radians) about the x axis (body: the nose axis — roll), as a 3 × 3 numpy array.
    Positive = right-hand rule: thumb along +x, fingers curl from +y towards +z.

    Example: rot_x(math.radians(90)) @ [0, 1, 0] → about [0, 0, 1]   (+y is carried to +z)
    """
    c, s = math.cos(angle_rad), math.sin(angle_rad)
    return np.array([[1.0, 0.0, 0.0],
                     [0.0, c, -s],
                     [0.0, s, c]])


# from mission 16 — finished: read it, use it, do not change it
def rot_y(angle_rad):
    """Rotation by angle_rad (radians) about the y axis (body: the LEFT wing axis — ROS pitch), as a
    3 × 3 numpy array. Positive = right-hand rule: thumb along +y, fingers curl from +z towards +x.

    Example: rot_y(math.radians(30)) @ [1, 0, 0] → about [0.866, 0, -0.5]   (nose 30° DOWN)
    """
    c, s = math.cos(angle_rad), math.sin(angle_rad)
    return np.array([[c, 0.0, s],
                     [0.0, 1.0, 0.0],
                     [-s, 0.0, c]])


# from mission 16 — finished: read it, use it, do not change it
def rot_z(angle_rad):
    """Rotation by angle_rad (radians) about the z axis (Up — yaw), as a 3 × 3 numpy array.
    Positive = right-hand rule: counter-clockwise seen from above, from +x (east) towards +y (north).

    Example: rot_z(math.radians(30)) @ [1, 0, 0] → about [0.866, 0.5, 0]
    """
    c, s = math.cos(angle_rad), math.sin(angle_rad)
    return np.array([[c, -s, 0.0],
                     [s, c, 0.0],
                     [0.0, 0.0, 1.0]])


# from mission 16 — finished: read it, use it, do not change it
def euler_zyx_to_matrix(roll_rad, pitch_rad, yaw_rad):
    """The attitude matrix of ROS ZYX Euler angles (radians): R = Rz(yaw) · Ry(pitch) · Rx(roll), 3 × 3
    numpy array, body (FLU) → world (ENU). ROS signs: roll positive = right wing down, pitch positive =
    nose DOWN, yaw positive = nose turns left (counter-clockwise from east).

    Example: euler_zyx_to_matrix(0.0, 0.0, math.radians(90)) → about [[0, -1, 0], [1, 0, 0], [0, 0, 1]]
             euler_zyx_to_matrix(math.radians(20), math.radians(-15), math.radians(-40))[:, 0]
             → about [0.7399, -0.6209, 0.2588]   (the nose: heading 130°, 15° UP)
    """
    return rot_z(yaw_rad) @ rot_y(pitch_rad) @ rot_x(roll_rad)


# from mission 16 — finished: read it, use it, do not change it
def matrix_to_euler_zyx(R):
    """The ROS ZYX Euler angles of a rotation matrix: (roll_rad, pitch_rad, yaw_rad, locked).
    pitch in [−π/2, π/2]; roll and yaw in [−π, π]. Clamp before asin (rounding can give 1.0000000002).
    Gimbal lock: when |cos(pitch)| < 1e-6 (nose straight up or down) roll and yaw cannot be separated:
    return roll = 0.0, yaw = atan2(−R[0][1], R[1][1]) and locked = True. Otherwise locked = False.

    Example: matrix_to_euler_zyx(euler_zyx_to_matrix(0.3, -0.2, 2.5)) → about (0.3, -0.2, 2.5, False)
             matrix_to_euler_zyx(euler_zyx_to_matrix(0.0, math.pi / 2, 0.5)) → about (0.0, 1.5708, 0.5, True)
    """
    R = np.asarray(R, dtype=float)
    s = max(-1.0, min(1.0, -R[2, 0]))
    pitch = math.asin(s)
    cos_p = math.hypot(R[0, 0], R[1, 0])
    if cos_p < 1e-6:
        return 0.0, pitch, math.atan2(-R[0, 1], R[1, 1]), True
    roll = math.atan2(R[2, 1], R[2, 2])
    yaw = math.atan2(R[1, 0], R[0, 0])
    return roll, pitch, yaw, False


