# from mission 16 — finished: read it, use it, do not change it
def q_mul(p, q):
    """The Hamilton product p ⊗ q of two quaternions in ROS order (x, y, z, w), as a numpy array.
    It composes rotations like matrices: the matrix of p ⊗ q is (matrix of p) @ (matrix of q).
    Not commutative: p ⊗ q ≠ q ⊗ p in general.

    Example: q_mul((1, 0, 0, 0), (0, 1, 0, 0)) → array([0., 0., 1., 0.])    (i ⊗ j = k)
             q_mul((0.0, 0.0, 0.6, 0.8), (0.0, 0.6, 0.0, 0.8)) → array([-0.36,  0.48,  0.48,  0.64])
             q_mul((0.0, 0.0, 0.6, 0.8), (0.0, 0.0, 0.6, 0.8)) → array([0.  , 0.  , 0.96, 0.28])
    """
    px, py, pz, pw = (float(v) for v in p)
    qx, qy, qz, qw = (float(v) for v in q)
    return np.array([pw * qx + px * qw + py * qz - pz * qy,
                     pw * qy - px * qz + py * qw + pz * qx,
                     pw * qz + px * qy - py * qx + pz * qw,
                     pw * qw - px * qx - py * qy - pz * qz])


# from mission 16 — finished: read it, use it, do not change it
def q_conj(q):
    """The conjugate of a quaternion (x, y, z, w): the vector part negated, w unchanged (numpy array).
    For a unit quaternion it is the inverse rotation.

    Example: q_conj((0.1, -0.2, 0.3, 0.9)) → array([-0.1,  0.2, -0.3,  0.9])
    """
    x, y, z, w = (float(v) for v in q)
    return np.array([-x, -y, -z, w])


# from mission 16 — finished: read it, use it, do not change it
def q_from_axis_angle(axis, angle_rad):
    """The unit quaternion (x, y, z, w) of a rotation by angle_rad (radians) about axis (3 numbers, any
    non-zero length: it is normalised first). Raises ValueError if the axis has zero length.

    Example: q_from_axis_angle((0, 0, 2), math.radians(60)) → about array([0. , 0. , 0.5, 0.866])
    """
    a = np.asarray(axis, dtype=float).reshape(3)
    n = float(np.linalg.norm(a))
    if n < 1e-12:
        raise ValueError(f"the rotation axis must not be zero, got {a.tolist()}")
    u = a / n
    h = angle_rad / 2.0
    return np.array([u[0] * math.sin(h), u[1] * math.sin(h), u[2] * math.sin(h), math.cos(h)])


# from mission 16 — finished: read it, use it, do not change it
def q_rotate(q, v):
    """The vector v (3 numbers) rotated by the unit quaternion q (x, y, z, w): q ⊗ (v, 0) ⊗ q*, keep the
    vector part. Returns a numpy array of 3 floats.

    Example: q_rotate((0.0, 0.0, 0.5, 0.866025), (2.0, 0.0, 0.0)) → about array([1.   , 1.732, 0.   ])
    """
    v = np.asarray(v, dtype=float).reshape(3)
    p = np.array([v[0], v[1], v[2], 0.0])
    r = q_mul(q_mul(q, p), q_conj(q))
    return r[:3]


# from mission 16 — finished: read it, use it, do not change it
def q_to_matrix(q):
    """The 3 × 3 rotation matrix (numpy array) of a quaternion (x, y, z, w). q is normalised first, so a
    slightly-off-length quaternion still gives a proper rotation.

    Example: q_to_matrix((0.0, 0.0, 0.5, 0.866025)) → about [[0.5, -0.866, 0], [0.866, 0.5, 0], [0, 0, 1]]
             q_to_matrix((0.0537, 0.0812, 0.4943, 0.8638))
             → about [[0.498, -0.845, 0.193], [0.863, 0.506, -0.013], [-0.087, 0.173, 0.981]]   (lesson §3's R)
    """
    x, y, z, w = q_normalize(q)
    return np.array([[1 - 2 * (y * y + z * z), 2 * (x * y - w * z), 2 * (x * z + w * y)],
                     [2 * (x * y + w * z), 1 - 2 * (x * x + z * z), 2 * (y * z - w * x)],
                     [2 * (x * z - w * y), 2 * (y * z + w * x), 1 - 2 * (x * x + y * y)]])


# from mission 16 — finished: read it, use it, do not change it
def slerp(q0, q1, t):
    """Spherical linear interpolation between two unit quaternions (x, y, z, w), t in [0, 1]: t = 0 gives
    q0, t = 1 gives q1 (or −q1, the same rotation), and the rotation turns at a constant rate in between.
    Takes the SHORTEST way (if q0 · q1 < 0, use −q1). When q0 · q1 > 0.9995 (almost the same attitude),
    use normalised linear interpolation instead (sin θ ≈ 0). Returns a unit numpy array.

    Example: slerp((0, 0, 0, 1), (0, 0, 1, 0), 0.5) → about array([0.    , 0.    , 0.7071, 0.7071])
             (half-way from no rotation to a 180° yaw: a 90° yaw)
    """
    a = np.asarray(q0, dtype=float).reshape(4)
    b = np.asarray(q1, dtype=float).reshape(4)
    d = float(a @ b)
    if d < 0.0:
        b, d = -b, -d
    if d > 0.9995:
        return q_normalize(a + t * (b - a))
    th = math.acos(min(1.0, d))
    out = (math.sin((1.0 - t) * th) * a + math.sin(t * th) * b) / math.sin(th)
    return q_normalize(out)


# from mission 16 — finished: read it, use it, do not change it
def q_angle_deg(q0, q1):
    """The angle (degrees, in [0, 180]) of the smallest rotation that turns attitude q0 into attitude q1
    (both unit quaternions, x, y, z, w). q and −q are the same attitude: the answer must not change if
    one of them is negated.

    Example: q_angle_deg((0, 0, 0, 1), (0, 0, 0.258819, 0.965926)) → about 30.0
             q_angle_deg((0, 0, 0, 1), (0, 0, 0, -1)) → 0.0
    """
    a = q_normalize(q0)
    b = q_normalize(q1)
    d = min(1.0, abs(float(a @ b)))
    return math.degrees(2.0 * math.acos(d))


# ====================================================================== given: the human angles

# from mission 16 — finished: read it, use it, do not change it
def q_from_euler_zyx(roll_rad, pitch_rad, yaw_rad):
    """The unit quaternion (x, y, z, w) of ROS ZYX Euler angles (radians): the same attitude as
    euler_zyx_to_matrix(roll, pitch, yaw). Built from YOUR functions: q_z(yaw) ⊗ q_y(pitch) ⊗ q_x(roll),
    the same order as Rz · Ry · Rx.

    Example: q_from_euler_zyx(0.0, 0.0, math.radians(90)) → about array([0.    , 0.    , 0.7071, 0.7071])
    """
    qz = q_from_axis_angle((0.0, 0.0, 1.0), yaw_rad)
    qy = q_from_axis_angle((0.0, 1.0, 0.0), pitch_rad)
    qx = q_from_axis_angle((1.0, 0.0, 0.0), roll_rad)
    return q_normalize(q_mul(q_mul(qz, qy), qx))


# from mission 16 — finished: read it, use it, do not change it
def heading_deg_from_q(q):
    """Heading of the nose (degrees clockwise from north, in [0, 360)) for an attitude quaternion
    (x, y, z, w) in ENU: the direction of the nose's horizontal shadow, atan2(east, north), from the
    first column of YOUR q_to_matrix. Returns math.nan when the nose points straight up or down.

    Example: heading_deg_from_q((0.0, 0.0, 0.0, 1.0)) → 90.0   (no rotation: the nose points east)
             heading_deg_from_q((0.0, 0.0, 0.7071068, 0.7071068)) → 0.0 (yaw +90°: north)
    """
    nose = q_to_matrix(q)[:, 0]
    east, north = float(nose[0]), float(nose[1])
    if math.hypot(east, north) < 1e-9:
        return math.nan
    return round(math.degrees(math.atan2(east, north)) % 360.0, 9) % 360.0


# from mission 16 — finished: read it, use it, do not change it
def rpy_human(q):
    """The attitude as a pilot reads it, in DEGREES: (roll, pitch_up, heading), from YOUR q_to_matrix and
    matrix_to_euler_zyx. roll: positive = right wing down (the same sign as the ROS roll); pitch_up:
    positive = nose UP (the OPPOSITE of the ROS pitch); heading: clockwise from north in [0, 360),
    heading = (90° − yaw) mod 360°. At gimbal lock your matrix_to_euler_zyx decides (roll 0).

    Example: rpy_human(q_from_euler_zyx(math.radians(10), math.radians(5), math.radians(60)))
             → about (10.0, -5.0, 30.0)   (ROS pitch +5° = nose 5° DOWN)
    """
    roll, pitch, yaw, _locked = matrix_to_euler_zyx(q_to_matrix(q))
    heading = round((90.0 - math.degrees(yaw)) % 360.0, 9) % 360.0
    return math.degrees(roll), -math.degrees(pitch), heading
